-- rule disjunction (row): parameterized; p1 numeric, p2 numeric, p3 text, p4 text, p5 numeric
SELECT t."parent_id", t."qty_per", count(*) AS "n" FROM "sxc_rules"."bom_line" t WHERE (t."child_id" IS NOT NULL) AND ((t."qty_per" IS NOT NULL AND t."qty_per" IN (CAST(:p1 AS numeric), CAST(:p2 AS numeric))) OR ((EXISTS (SELECT 1 FROM "sxc_rules"."part" n WHERE n."part_id" = t."child_id" AND (n."unit" IS NOT NULL AND n."unit" IN (CAST(:p3 AS text), CAST(:p4 AS text))))) AND (t."qty_per" IS NOT NULL AND t."qty_per" >= CAST(:p5 AS numeric))) OR (t."line_id" IS NULL)) GROUP BY t."parent_id", t."qty_per";

-- rule disjunction: view
CREATE OR REPLACE VIEW "sxc_out"."v_rule_disjunction" AS
SELECT r.*, row_number() OVER (ORDER BY r."parent_id" COLLATE "C" NULLS FIRST, r."qty_per" NULLS FIRST, r."n" NULLS FIRST) AS ord FROM (SELECT t."parent_id", t."qty_per", count(*) AS "n" FROM "sxc_rules"."bom_line" t WHERE (t."child_id" IS NOT NULL) AND ((t."qty_per" IS NOT NULL AND t."qty_per" IN (CAST(E'8642.75' AS numeric), CAST(E'13.579' AS numeric))) OR ((EXISTS (SELECT 1 FROM "sxc_rules"."part" n WHERE n."part_id" = t."child_id" AND (n."unit" IS NOT NULL AND n."unit" IN (CAST(E'DRPMARK-pc' AS text), CAST(E'DRPMARK-box' AS text))))) AND (t."qty_per" IS NOT NULL AND t."qty_per" >= CAST(E'0.4321' AS numeric))) OR (t."line_id" IS NULL)) GROUP BY t."parent_id", t."qty_per") r;

-- example disjunction[0]: parameterized; 15 parameters
WITH "sxc_ex_bom_line"("child_id", "qty_per", "line_id", "parent_id") AS (VALUES (CAST(:p1 AS text), CAST(:p2 AS numeric(18,6)), CAST(:p3 AS integer), CAST(:p4 AS text)), (CAST(:p5 AS text), CAST(:p6 AS numeric(18,6)), CAST(:p7 AS integer), CAST(:p8 AS text))), "sxc_ex_part"("part_id", "unit") AS (VALUES (CAST(:p9 AS text), CAST(:p10 AS text))) SELECT * FROM (SELECT t."parent_id", t."qty_per", count(*) AS "n" FROM "sxc_ex_bom_line" t WHERE (t."child_id" IS NOT NULL) AND ((t."qty_per" IS NOT NULL AND t."qty_per" IN (CAST(:p11 AS numeric), CAST(:p12 AS numeric))) OR ((EXISTS (SELECT 1 FROM "sxc_ex_part" n WHERE n."part_id" = t."child_id" AND (n."unit" IS NOT NULL AND n."unit" IN (CAST(:p13 AS text), CAST(:p14 AS text))))) AND (t."qty_per" IS NOT NULL AND t."qty_per" >= CAST(:p15 AS numeric))) OR (t."line_id" IS NULL)) GROUP BY t."parent_id", t."qty_per") r;

