-- rule code_rows (row): parameterized; p1 text, p2 text, p3 text
SELECT t."code_group", t."code" FROM "sxc_rules"."code_value" t WHERE (t."code" IS NOT NULL AND (starts_with(t."code", CAST(:p1 AS text)) OR starts_with(t."code", CAST(:p2 AS text)))) AND (t."code_group" IS NOT NULL AND t."code_group" <> CAST(:p3 AS text));

-- rule code_rows: view
CREATE OR REPLACE VIEW "sxc_out"."v_rule_code_rows" AS
SELECT r.*, row_number() OVER (ORDER BY r."code_group" COLLATE "C" NULLS FIRST, r."code" COLLATE "C" NULLS FIRST) AS ord FROM (SELECT t."code_group", t."code" FROM "sxc_rules"."code_value" t WHERE (t."code" IS NOT NULL AND (starts_with(t."code", CAST(E'DRPMARK-TMP-' AS text)) OR starts_with(t."code", CAST(E'DRPMARK-OLD-' AS text)))) AND (t."code_group" IS NOT NULL AND t."code_group" <> CAST(E'DRPMARK-X' AS text))) r;

-- rule duplicate_endpoints (duplicate): parameterized; p1 bigint
SELECT np."part_class" AS "parent_part_class", nc."name" AS "child_name", t."qty_per", count(*) AS "n" FROM "sxc_rules"."bom_line" t JOIN "sxc_rules"."part" np ON np."part_id" = t."parent_id" JOIN "sxc_rules"."part" nc ON nc."part_id" = t."child_id" WHERE np."part_class" IS NOT NULL AND nc."name" IS NOT NULL AND t."qty_per" IS NOT NULL GROUP BY np."part_class", nc."name", t."qty_per" HAVING count(*) >= CAST(:p1 AS bigint);

-- rule duplicate_endpoints: view
CREATE OR REPLACE VIEW "sxc_out"."v_rule_duplicate_endpoints" AS
SELECT r.*, row_number() OVER (ORDER BY r."parent_part_class" COLLATE "C" NULLS FIRST, r."child_name" COLLATE "C" NULLS FIRST, r."qty_per" NULLS FIRST, r."n" NULLS FIRST) AS ord FROM (SELECT np."part_class" AS "parent_part_class", nc."name" AS "child_name", t."qty_per", count(*) AS "n" FROM "sxc_rules"."bom_line" t JOIN "sxc_rules"."part" np ON np."part_id" = t."parent_id" JOIN "sxc_rules"."part" nc ON nc."part_id" = t."child_id" WHERE np."part_class" IS NOT NULL AND nc."name" IS NOT NULL AND t."qty_per" IS NOT NULL GROUP BY np."part_class", nc."name", t."qty_per" HAVING count(*) >= CAST(E'86420' AS bigint)) r;

-- rule duplicate_distinct (duplicate): parameterized; p1 bigint
SELECT DISTINCT d."child_id" FROM (SELECT t."child_id" AS "child_id" FROM "sxc_rules"."bom_line" t JOIN "sxc_rules"."part" nc ON nc."part_id" = t."child_id" WHERE t."child_id" IS NOT NULL AND nc."unit" IS NOT NULL GROUP BY t."child_id", nc."unit" HAVING count(DISTINCT t."parent_id") >= CAST(:p1 AS bigint)) d WHERE d."child_id" IS NOT NULL;

-- rule duplicate_distinct: view
CREATE OR REPLACE VIEW "sxc_out"."v_rule_duplicate_distinct" AS
SELECT r.*, row_number() OVER (ORDER BY r."child_id" COLLATE "C" NULLS FIRST) AS ord FROM (SELECT DISTINCT d."child_id" FROM (SELECT t."child_id" AS "child_id" FROM "sxc_rules"."bom_line" t JOIN "sxc_rules"."part" nc ON nc."part_id" = t."child_id" WHERE t."child_id" IS NOT NULL AND nc."unit" IS NOT NULL GROUP BY t."child_id", nc."unit" HAVING count(DISTINCT t."parent_id") >= CAST(E'75319' AS bigint)) d WHERE d."child_id" IS NOT NULL) r;

-- rule mode_plain (mode_outlier): parameterized; p1 numeric, p2 numeric, p3 numeric
WITH g AS (SELECT t."parent_id" AS grp, count(*) AS n_rows FROM "sxc_rules"."bom_line" t WHERE t."parent_id" IS NOT NULL GROUP BY t."parent_id"), f AS (SELECT t."parent_id" AS grp, t."qty_per" AS val, count(*) AS n_val FROM "sxc_rules"."bom_line" t WHERE t."parent_id" IS NOT NULL AND t."qty_per" IS NOT NULL GROUP BY t."parent_id", t."qty_per"), m AS (SELECT f.grp, f.val AS mode_value FROM f JOIN g ON g.grp = f.grp WHERE f.n_val * CAST(:p1 AS numeric) >= CAST(:p2 AS numeric) * g.n_rows AND f.val > 0) SELECT t."line_id" FROM "sxc_rules"."bom_line" t JOIN m ON m.grp = t."parent_id" WHERE t."qty_per" IS NOT NULL AND (t."qty_per" >= CAST(:p3 AS numeric) * m.mode_value OR CAST(:p3 AS numeric) * t."qty_per" <= m.mode_value);

-- rule mode_plain: view
CREATE OR REPLACE VIEW "sxc_out"."v_rule_mode_plain" AS
SELECT r.*, row_number() OVER (ORDER BY r."line_id" NULLS FIRST) AS ord FROM (WITH g AS (SELECT t."parent_id" AS grp, count(*) AS n_rows FROM "sxc_rules"."bom_line" t WHERE t."parent_id" IS NOT NULL GROUP BY t."parent_id"), f AS (SELECT t."parent_id" AS grp, t."qty_per" AS val, count(*) AS n_val FROM "sxc_rules"."bom_line" t WHERE t."parent_id" IS NOT NULL AND t."qty_per" IS NOT NULL GROUP BY t."parent_id", t."qty_per"), m AS (SELECT f.grp, f.val AS mode_value FROM f JOIN g ON g.grp = f.grp WHERE f.n_val * CAST(E'10000' AS numeric) >= CAST(E'9753' AS numeric) * g.n_rows AND f.val > 0) SELECT t."line_id" FROM "sxc_rules"."bom_line" t JOIN m ON m.grp = t."parent_id" WHERE t."qty_per" IS NOT NULL AND (t."qty_per" >= CAST(E'13.579' AS numeric) * m.mode_value OR CAST(E'13.579' AS numeric) * t."qty_per" <= m.mode_value)) r;

-- rule mode_distinct (mode_outlier): parameterized; p1 bigint, p2 numeric, p3 numeric, p4 numeric
WITH g AS (SELECT t."child_id" AS grp, count(*) AS n_rows, count(DISTINCT t."line_id") AS n_distinct FROM "sxc_rules"."bom_line" t WHERE t."child_id" IS NOT NULL GROUP BY t."child_id"), f AS (SELECT t."child_id" AS grp, t."qty_per" AS val, count(*) AS n_val FROM "sxc_rules"."bom_line" t WHERE t."child_id" IS NOT NULL AND t."qty_per" IS NOT NULL GROUP BY t."child_id", t."qty_per"), m AS (SELECT f.grp, f.val AS mode_value FROM f JOIN g ON g.grp = f.grp WHERE g.n_distinct >= CAST(:p1 AS bigint) AND f.n_val * CAST(:p2 AS numeric) >= CAST(:p3 AS numeric) * g.n_rows AND f.val > 0) SELECT DISTINCT t."parent_id" FROM "sxc_rules"."bom_line" t JOIN m ON m.grp = t."child_id" WHERE t."qty_per" IS NOT NULL AND (t."qty_per" >= CAST(:p4 AS numeric) * m.mode_value OR CAST(:p4 AS numeric) * t."qty_per" <= m.mode_value) AND t."parent_id" IS NOT NULL;

-- rule mode_distinct: view
CREATE OR REPLACE VIEW "sxc_out"."v_rule_mode_distinct" AS
SELECT r.*, row_number() OVER (ORDER BY r."parent_id" COLLATE "C" NULLS FIRST) AS ord FROM (WITH g AS (SELECT t."child_id" AS grp, count(*) AS n_rows, count(DISTINCT t."line_id") AS n_distinct FROM "sxc_rules"."bom_line" t WHERE t."child_id" IS NOT NULL GROUP BY t."child_id"), f AS (SELECT t."child_id" AS grp, t."qty_per" AS val, count(*) AS n_val FROM "sxc_rules"."bom_line" t WHERE t."child_id" IS NOT NULL AND t."qty_per" IS NOT NULL GROUP BY t."child_id", t."qty_per"), m AS (SELECT f.grp, f.val AS mode_value FROM f JOIN g ON g.grp = f.grp WHERE g.n_distinct >= CAST(E'64208' AS bigint) AND f.n_val * CAST(E'1' AS numeric) >= CAST(E'1' AS numeric) * g.n_rows AND f.val > 0) SELECT DISTINCT t."parent_id" FROM "sxc_rules"."bom_line" t JOIN m ON m.grp = t."child_id" WHERE t."qty_per" IS NOT NULL AND (t."qty_per" >= CAST(E'8642.75' AS numeric) * m.mode_value OR CAST(E'8642.75' AS numeric) * t."qty_per" <= m.mode_value) AND t."parent_id" IS NOT NULL) r;

-- rule same_attrs (same_signature): parameterized; p1 bigint
WITH e AS (SELECT t."parent_id" AS node, t."child_id" AS kid, sum(t."qty_per") AS qsum FROM "sxc_rules"."bom_line" t WHERE t."parent_id" IS NOT NULL AND t."child_id" IS NOT NULL GROUP BY t."parent_id", t."child_id"), s AS (SELECT e.node, string_agg(encode(convert_to(e.kid, 'UTF8'), 'hex') || ':' || CAST(trim_scale(e.qsum) AS text), ',' ORDER BY e.kid COLLATE "C") AS sig FROM e GROUP BY e.node), k AS (SELECT n."part_id" AS member, s.sig, n."unit" AS a1 FROM s JOIN "sxc_rules"."part" n ON n."part_id" = s.node), c AS (SELECT k.member, min(k.member COLLATE "C") OVER w AS group_id, count(*) OVER w AS members FROM k WINDOW w AS (PARTITION BY k.sig, k.a1)) SELECT c.group_id AS "group_id", c.member AS "member" FROM c WHERE c.members >= CAST(:p1 AS bigint);

-- rule same_attrs: view
CREATE OR REPLACE VIEW "sxc_out"."v_rule_same_attrs" AS
SELECT r.*, row_number() OVER (ORDER BY r."group_id" COLLATE "C" NULLS FIRST, r."member" COLLATE "C" NULLS FIRST) AS ord FROM (WITH e AS (SELECT t."parent_id" AS node, t."child_id" AS kid, sum(t."qty_per") AS qsum FROM "sxc_rules"."bom_line" t WHERE t."parent_id" IS NOT NULL AND t."child_id" IS NOT NULL GROUP BY t."parent_id", t."child_id"), s AS (SELECT e.node, string_agg(encode(convert_to(e.kid, 'UTF8'), 'hex') || ':' || CAST(trim_scale(e.qsum) AS text), ',' ORDER BY e.kid COLLATE "C") AS sig FROM e GROUP BY e.node), k AS (SELECT n."part_id" AS member, s.sig, n."unit" AS a1 FROM s JOIN "sxc_rules"."part" n ON n."part_id" = s.node), c AS (SELECT k.member, min(k.member COLLATE "C") OVER w AS group_id, count(*) OVER w AS members FROM k WINDOW w AS (PARTITION BY k.sig, k.a1)) SELECT c.group_id AS "group_id", c.member AS "member" FROM c WHERE c.members >= CAST(E'86420' AS bigint)) r;

-- rule stored_height (stored_metric): parameterized; p1 bigint
WITH RECURSIVE edge AS (SELECT DISTINCT t."parent_id" AS p, t."child_id" AS c FROM "sxc_rules"."bom_line" t WHERE t."parent_id" IS NOT NULL AND t."child_id" IS NOT NULL), h(node, d) AS (SELECT e.c, 0 FROM edge e WHERE NOT EXISTS (SELECT 1 FROM edge x WHERE x.p = e.c) UNION SELECT e.p, h.d + 1 FROM edge e JOIN h ON e.c = h.node WHERE h.d < CAST(:p1 AS bigint)), ht AS (SELECT h.node, max(h.d) AS height FROM h GROUP BY h.node) SELECT n."part_id", CASE WHEN EXISTS (SELECT 1 FROM edge x WHERE x.p = n."part_id") THEN CASE WHEN n."stored_level" = 0 THEN 'has_children_stored_zero' WHEN n."stored_level" < ht.height THEN 'stored_below' ELSE 'stored_above' END WHEN EXISTS (SELECT 1 FROM edge x WHERE x.c = n."part_id") THEN 'leaf_stored_nonzero' ELSE 'outside_stored_nonzero' END AS "kind", n."stored_level" AS "stored", COALESCE(ht.height, 0) AS "height" FROM "sxc_rules"."part" n LEFT JOIN ht ON ht.node = n."part_id" WHERE n."stored_level" IS NOT NULL AND n."stored_level" <> COALESCE(ht.height, 0);

-- rule stored_height: view
CREATE OR REPLACE VIEW "sxc_out"."v_rule_stored_height" AS
SELECT r.*, row_number() OVER (ORDER BY r."part_id" COLLATE "C" NULLS FIRST, r."kind" COLLATE "C" NULLS FIRST, r."stored" NULLS FIRST, r."height" NULLS FIRST) AS ord FROM (WITH RECURSIVE edge AS (SELECT DISTINCT t."parent_id" AS p, t."child_id" AS c FROM "sxc_rules"."bom_line" t WHERE t."parent_id" IS NOT NULL AND t."child_id" IS NOT NULL), h(node, d) AS (SELECT e.c, 0 FROM edge e WHERE NOT EXISTS (SELECT 1 FROM edge x WHERE x.p = e.c) UNION SELECT e.p, h.d + 1 FROM edge e JOIN h ON e.c = h.node WHERE h.d < CAST(E'13' AS bigint)), ht AS (SELECT h.node, max(h.d) AS height FROM h GROUP BY h.node) SELECT n."part_id", CASE WHEN EXISTS (SELECT 1 FROM edge x WHERE x.p = n."part_id") THEN CASE WHEN n."stored_level" = 0 THEN 'has_children_stored_zero' WHEN n."stored_level" < ht.height THEN 'stored_below' ELSE 'stored_above' END WHEN EXISTS (SELECT 1 FROM edge x WHERE x.c = n."part_id") THEN 'leaf_stored_nonzero' ELSE 'outside_stored_nonzero' END AS "kind", n."stored_level" AS "stored", COALESCE(ht.height, 0) AS "height" FROM "sxc_rules"."part" n LEFT JOIN ht ON ht.node = n."part_id" WHERE n."stored_level" IS NOT NULL AND n."stored_level" <> COALESCE(ht.height, 0)) r;

-- rule text_one_capture (text_quantity): parameterized; p1 text, p2 text, p3 numeric
SELECT t."line_id" FROM "sxc_rules"."bom_line" t JOIN "sxc_rules"."part" en ON en."part_id" = t."parent_id" CROSS JOIN LATERAL (SELECT regexp_match(en."name", CAST(:p1 AS text)) AS g) rx CROSS JOIN LATERAL (SELECT CASE WHEN rx.g[1] ~ CAST(:p2 AS text) THEN CAST(rx.g[1] AS numeric) END AS numerator, CAST(1 AS numeric) AS divisor) x WHERE t."qty_per" IS NOT NULL AND rx.g IS NOT NULL AND x.numerator > 0 AND x.divisor > 0 AND abs(t."qty_per" * x.divisor - x.numerator) <= CAST(:p3 AS numeric) * x.numerator;

-- rule text_one_capture: view
CREATE OR REPLACE VIEW "sxc_out"."v_rule_text_one_capture" AS
SELECT r.*, row_number() OVER (ORDER BY r."line_id" NULLS FIRST) AS ord FROM (SELECT t."line_id" FROM "sxc_rules"."bom_line" t JOIN "sxc_rules"."part" en ON en."part_id" = t."parent_id" CROSS JOIN LATERAL (SELECT regexp_match(en."name", CAST(E'DRPMARK([0-9]+) ?kg$' AS text)) AS g) rx CROSS JOIN LATERAL (SELECT CASE WHEN rx.g[1] ~ CAST(E'^[0-9]+(\\.[0-9]+)?$' AS text) THEN CAST(rx.g[1] AS numeric) END AS numerator, CAST(1 AS numeric) AS divisor) x WHERE t."qty_per" IS NOT NULL AND rx.g IS NOT NULL AND x.numerator > 0 AND x.divisor > 0 AND abs(t."qty_per" * x.divisor - x.numerator) <= CAST(E'0.4321' AS numeric) * x.numerator) r;

-- rule text_distinct (text_quantity): parameterized; p1 text, p2 text, p3 text, p4 text, p5 text, p6 numeric
SELECT DISTINCT t."parent_id" FROM "sxc_rules"."bom_line" t JOIN "sxc_rules"."part" en ON en."part_id" = t."child_id" CROSS JOIN LATERAL (SELECT regexp_match(en."name", CAST(:p1 AS text)) AS g) rx CROSS JOIN LATERAL (SELECT CASE WHEN rx.g[1] ~ CAST(:p2 AS text) THEN CAST(rx.g[1] AS numeric) END AS numerator, CASE WHEN rx.g[2] IS NULL THEN CAST(1 AS numeric) WHEN rx.g[2] ~ CAST(:p3 AS text) THEN CAST(rx.g[2] AS numeric) END AS divisor) x WHERE (en."unit" IS NOT NULL AND en."unit" NOT IN (CAST(:p4 AS text), CAST(:p5 AS text))) AND t."qty_per" IS NOT NULL AND rx.g IS NOT NULL AND x.numerator > 0 AND x.divisor > 0 AND abs(t."qty_per" * x.divisor - x.numerator) <= CAST(:p6 AS numeric) * x.numerator AND t."parent_id" IS NOT NULL;

-- rule text_distinct: view
CREATE OR REPLACE VIEW "sxc_out"."v_rule_text_distinct" AS
SELECT r.*, row_number() OVER (ORDER BY r."parent_id" COLLATE "C" NULLS FIRST) AS ord FROM (SELECT DISTINCT t."parent_id" FROM "sxc_rules"."bom_line" t JOIN "sxc_rules"."part" en ON en."part_id" = t."child_id" CROSS JOIN LATERAL (SELECT regexp_match(en."name", CAST(E'DRPMARK([0-9.]+)(?:\\/([0-9]+))?' AS text)) AS g) rx CROSS JOIN LATERAL (SELECT CASE WHEN rx.g[1] ~ CAST(E'^[0-9]+(\\.[0-9]+)?$' AS text) THEN CAST(rx.g[1] AS numeric) END AS numerator, CASE WHEN rx.g[2] IS NULL THEN CAST(1 AS numeric) WHEN rx.g[2] ~ CAST(E'^[0-9]+$' AS text) THEN CAST(rx.g[2] AS numeric) END AS divisor) x WHERE (en."unit" IS NOT NULL AND en."unit" NOT IN (CAST(E'DRPMARK-pc' AS text), CAST(E'DRPMARK-box' AS text))) AND t."qty_per" IS NOT NULL AND rx.g IS NOT NULL AND x.numerator > 0 AND x.divisor > 0 AND abs(t."qty_per" * x.divisor - x.numerator) <= CAST(E'13.579' AS numeric) * x.numerator AND t."parent_id" IS NOT NULL) r;
